function [ yuv_data ] = rgb2yuv( frame,display_mode,golbal_bitdepth_parameter) %version 5.0 HDTVpix_r=double(round(frame(:, :, 1)));pix_g=double(round(frame(:, :, 2)));pix_b=double(round(frame(:, :, 3)));[h,w]=size(pix_r);if golbal_bitdepth_parameter == 10    offset1 = 512 ;    offset2 = 64 ;elseif golbal_bitdepth_parameter == 8    offset1 = 128;    offset2 = 16 ;endif strcmp(display_mode,'BT709')  y=fix( (pix_r*55 + pix_g*183 + pix_b*19 + 128 ) / 256 );  u=fix( (pix_b*131 + 128 + offset1*256- pix_r*30  - pix_g*101) / 256);  v=fix( (pix_r*131 + 128 + offset1*256 - pix_g*119 - pix_b*12)  / 256);else  y=fix((pix_r* 47+pix_g* 157+pix_b* 16+128+offset2*256)/256);  u=fix((pix_b* 112 + 128+offset1-pix_r* 26-pix_g* 87)/256);  v=fix((pix_r* 112 + 128+offset1-pix_g* 102-pix_b*10)/256);endfor i = 1:h    for j = 1:w        if(y(i,j)>=2^(golbal_bitdepth_parameter))             y(i,j)=2^(golbal_bitdepth_parameter)-1;        elseif(y(i,j)<0)             y(i,j)=0;        else             y(i,j)=fix(y(i,j));        end                        if(u(i,j)>=2^(golbal_bitdepth_parameter))             u(i,j)=2^(golbal_bitdepth_parameter)-1;        elseif(u(i,j)<0)             u(i,j)=0;        else             u(i,j)=fix(u(i,j));        end                        if(v(i,j)>=2^(golbal_bitdepth_parameter))             v(i,j)=2^(golbal_bitdepth_parameter)-1;        elseif(v(i,j)<0)             v(i,j)=0;        else             v(i,j)=fix(v(i,j));        end                    endendyuv_data(:, :, 1)=y;yuv_data(:, :, 2)=u;yuv_data(:, :, 3)=v;% close(ll);end